contracts/AidStream.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
 * AidStream.sol
 * ------------------------------------------
 * Main donation tracking contract for AidStream.
 *
 * Features:
 * - Create beneficiary aid cases
 * - Donate to verified cases
 * - Track donations transparently
 * - Store donor history
 * - Emit blockchain events
 *
 * NOTE:
 * Escrow release logic can later be delegated
 * to Escrow.sol for better modularity.
 */

 import "@openzeppelin/contracts/access/Ownable.sol";
 import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

 contract AidStream is Ownable, ReentrancyGuard {
    // STRUCTS

    struct Case {
        uint256 id;
        string title;
        string description;
        address payable beneficiary;
        uint256 goalAmount;
        uint256 donatedAmount;
        bool verified;
        bool fundsReleased;
        bool active;
        uint256 createdAt;
    }

    struct Donation {
        address donor;
        uint256 amount;
        uint256 timestamp;
    }

    // STATE VARIABLES

    uint256 public caseCount;

    mapping(uint256 => Case) public cases;

    mapping(uint256 => Donation[]) public caseDonations;

    mapping(address => uint256[]) public donorHistory;

    mapping(address => bool) public validators;

    // EVENTS

    event CaseCreated(
        uint256 indexed caseId,
        string title,
        address indexed beneficiary,
        uint256 goalAmount
    );

    event CaseVerified(
        uint256 indexed caseId,
        address indexed validator
    );

    event DonationReceived(
        uint256 indexed caseId,
        address indexed donor,
        uint256 amount
    );

    event FundsReleased(
        uint256 indexed caseId,
        address indexed beneficiary,
        uint256 amount
    );

    event ValidatorAdded(address indexed validator);

    // MODIFIERS

    modifier onlyValidator() {
        require(validators[msg.sender], "Not an authorized validator");
        _;
    }

    modifier caseExists(uint256 _caseId) {
        require(_caseId > 0 && _caseId <= caseCount, "Case does not exist");
        _;
    }

    modifier caseIsActive(uint256 _caseId) {
        require(cases[_caseId].active, "Case is not active");
        _;
    }

    // CONSTRUCTOR

    constructor() Ownable(msg.sender) {}

    // ADMIN FUNCTIONS

    function addValidator(address _validator) external onlyOwner {
        require(_validator != address(0), "Invalid address");

        validators[_validator] = true;

        emit ValidatorAdded(_validator);
    }

    // CASE MANAGEMENT

    function createCase(
        string memory _title,
        string memory _description,
        address payable _beneficiary,
        uint256 _goalAmount
    ) external {
        require(bytes(_title).length > 0, "Title required");
        require(_beneficiary != address(0), "Invalid beneficiary");
        require(_goalAmount > 0, "Goal amount must be greater than zero");

        caseCount++;

        cases[caseCount] = Case({
            id: caseCount,
            title: _title,
            description: _description,
            beneficiary: _beneficiary,
            goalAmount: _goalAmount,
            donatedAmount: 0,
            verified: false,
            fundsReleased: false,
            active: true,
            createdAt: block.timestamp
        });

        emit CaseCreated(
            caseCount,
            _title,
            _beneficiary,
            _goalAmount
        );
    }

    // VERIFICATION

    function verifyCase(
        uint256 _caseId
    )
        external
        onlyValidator
        caseExists(_caseId)
    {
        Case storage aidCase = cases[_caseId];

        require(!aidCase.verified, "Case already verified");

        aidCase.verified = true;

        emit CaseVerified(_caseId, msg.sender);
    }

    // DONATIONS 

    function donateToCase(
        uint256 _caseId
    )
        external
        payable
        nonReentrant
        caseExists(_caseId)
        caseIsActive(_caseId)
    {
        require(msg.value > 0, "Donation amount must be greater than zero");

        Case storage aidCase = cases[_caseId];

        require(aidCase.verified, "Case is not verified");

        aidCase.donatedAmount += msg.value;

        caseDonations[_caseId].push(
            Donation({
                donor: msg.sender,
                amount: msg.value,
                timestamp: block.timestamp
            })
        );

        donorHistory[msg.sender].push(_caseId);

        emit DonationReceived(
            _caseId,
            msg.sender,
            msg.value
        );
    }

    // FUND RELEASE 

    function releaseFunds(
        uint256 _caseId
    )
        external
        onlyOwner
        nonReentrant
        caseExists(_caseId)
    {
        Case storage aidCase = cases[_caseId];

        require(aidCase.verified, "Case is not verified");
        require(!aidCase.fundsReleased, "Funds already released");
        require(aidCase.donatedAmount > 0, "No funds available");

        uint256 amount = aidCase.donatedAmount;

        aidCase.fundsReleased = true;
        aidCase.active = false;

        (bool success, ) = aidCase.beneficiary.call{value: amount}("");

        require(success, "Transfer failed");

        emit FundsReleased(
            _caseId,
            aidCase.beneficiary,
            amount
        );
    }

    // VIEW FUNCTIONS

    function getCase(
        uint256 _caseId
    )
        external
        view 
        caseExists(_caseId)
        returns (Case memory)
    {
        return cases[_caseId];
    }

    function getCaseDonations(
        uint256 _caseId
    )
        external
        view
        caseExists(_caseId)
        returns (Donation[] memory)
    {
        return caseDonations[_caseId];
    }

    function getDonorHistory(
        address _donor
    )
        external
        view
        returns (uint256[] memory)
    {
        return donorHistory[_donor];
    }

    function getContractBalance()
        external
        view
        returns (uint256)
    {
        return address(this).balance;
    }
 }

contracts/Escrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
 * Escrow.sol
 * --------------------------------------------------------
 * AidStream Escrow Contract
 *
 * Responsibilities:
 * - Lock donated funds securely
 * - Release funds only after approval
 * - Prevent double withdrawals
 * - Maintain transparent transaction history
 *
 * Security:
 * - Ownable access control
 * - Reentrancy protection
 * - Validations for releases and deposits
 */

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract Escrow is Ownable, ReentrancyGuard {

    // STRUCTS

    struct EscrowCase {
        uint256 caseId;
        address payable beneficiary;
        uint256 totalFunds;
        bool verified;
        bool released;
        uint256 createdAt;
    }

    // STATE VARIABLES

    mapping(uint256 => EscrowCase) public escrowCases;

    mapping(uint256 => mapping(address => uint256)) public donorContributions;

    mapping(address => bool) public validators;

    // EVENTS

    event EscrowCreated(
        uint256 indexed caseId,
        address indexed beneficiary
    );

    event FundsDeposited(
        uint256 indexed caseId,
        address indexed donor,
        uint256 amount
    );

    event CaseVerified(
        uint256 indexed caseId,
        address indexed validator
    );

    event FundsReleased(
        uint256 indexed caseId,
        address indexed beneficiary,
        uint256 amount
    );

    event ValidatorAdded(address indexed validator);

    // MODIFIER

    modifier onlyValidator() {
        require(
            validators[msg.sender],
            "Not an authorized validator"
        );
        _;
    }

    modifier escrowExists(uint256 _caseId) {
        require(
            escrowCases[_caseId].beneficiary != address(0),
            "Escrow case does not exist"
        );
        _;
    }

    // CONSTRUCTOR

    constructor() Ownable(msg.sender) {}

    // VALIDATOR MANAGEMENT

    function addValidator(
        address _validator
    ) external onlyOwner {

        require(
            _validator != address(0),
            "Invalid validator address"
        );

        validators[_validator] = true;

        emit ValidatorAdded(_validator);
    }

    // ESCROW MANAGEMENT

    function createEscrow(
        uint256 _caseId,
        address payable _beneficiary
    ) external onlyOwner {

        require(
            _beneficiary != address(0),
            "Invalid beneficiary address"
        );

        require(
            escrowCases[_caseId].beneficiary == address(0),
            "Escrow already exists"
        );

        escrowCases[_caseId] = EscrowCase({
            caseId: _caseId,
            beneficiary: _beneficiary,
            totalFunds: 0,
            verified: false,
            released: false,
            createdAt: block.timestamp
        });

        emit EscrowCreated(
            _caseId,
            _beneficiary
        );
    }

    // DONATIONS

    function depositFunds(
        uint256 _caseId
    )
        external
        payable
        nonReentrant
        escrowExists(_caseId)
    {

        require(
            msg.value > 0,
            "Deposit amount must be greater than zero"
        );

        EscrowCase storage escrowCase = escrowCases[_caseId];

        require(
            !escrowCase.released,
            "Funds already released"
        );

        escrowCase.totalFunds += msg.value;

        donorContributions[_caseId][msg.sender] += msg.value;

        emit FundsDeposited(
            _caseId,
            msg.sender,
            msg.value
        );
    }

    // VERIFICATION

    function verifyEscrowCase(
        uint256 _caseId
    )
        external
        onlyValidator
        escrowExists(_caseId)
    {

        EscrowCase storage escrowCase = escrowCases[_caseId];

        require(
            !escrowCase.verified,
            "Case already verified"
        );

        escrowCase.verified = true;

        emit CaseVerified(
            _caseId,
            msg.sender
        );
    }

    // FUND RELEASE

    function releaseFunds(
        uint256 _caseId
    )
        external
        onlyOwner
        nonReentrant
        escrowExists(_caseId)
    {

        EscrowCase storage escrowCase = escrowCases[_caseId];

        require(
            escrowCase.verified,
            "Case is not verified"
        );

        require(
            !escrowCase.released,
            "Funds already released"
        );

        require(
            escrowCase.totalFunds > 0,
            "No funds available"
        );

        uint256 amount = escrowCase.totalFunds;

        escrowCase.released = true;

        (bool success, ) = escrowCase.beneficiary.call{
            value: amount
        }("");

        require(
            success,
            "Transfer failed"
        );

        emit FundsReleased(
            _caseId,
            escrowCase.beneficiary,
            amount
        );
    }

    // VIEW FUNCTIONS

    function getEscrowCase(
        uint256 _caseId
    )
        external
        view
        escrowExists(_caseId)
        returns (EscrowCase memory)
    {
        return escrowCases[_caseId];
    }

    function getContribution(
        uint256 _caseId,
        address _donor
    )
        external
        view
        returns (uint256)
    {
        return donorContributions[_caseId][_donor];
    }

    function getContractBalance()
        external
        view
        returns (uint256)
    {
        return address(this).balance;
    }
}

contracts/VerificationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
 * VerificationRegistry.sol
 * --------------------------------------------------------
 * AidStream Verification Registry
 *
 * Responsibilities:
 * - Register validators
 * - Verify beneficiary cases
 * - Store verification approvals
 * - Maintain transparent verification history
 *
 * Security:
 * - Ownable access control
 * - Validator authorization checks
 * - Duplicate verification prevention
 */

import "@openzeppelin/contracts/access/Ownable.sol";

contract VerificationRegistry is Ownable {

    // STRUCTS

    struct VerificationCase {
        uint256 caseId;
        bool verified;
        uint256 approvalCount;
        uint256 createdAt;
    }

    struct VerificationRecord {
        address validator;
        uint256 timestamp;
    }

    // STATE VARIABLES

    mapping(address => bool) public validators;

    mapping(uint256 => VerificationCase) public verificationCases;

    mapping(uint256 => VerificationRecord[]) public verificationHistory;

    mapping(uint256 => mapping(address => bool))
        public hasVerified;

    uint256 public validatorCount;

    // EVENTS

    event ValidatorAdded(address indexed validator);

    event ValidatorRemoved(address indexed validator);

    event CaseCreated(uint256 indexed caseId);

    event CaseVerified(
        uint256 indexed caseId,
        address indexed validator
    );

    event CaseApproved(
        uint256 indexed caseId
    );

    // MODIFIERS

    modifier onlyValidator() {
        require(
            validators[msg.sender],
            "Not an authorized validator"
        );
        _;
    }

    modifier caseExists(uint256 _caseId) {
        require(
            verificationCases[_caseId].createdAt > 0,
            "Verification case does not exist"
        );
        _;
    }

    // CONSTRUCTOR

    constructor() Ownable(msg.sender) {}

    // VALIDATOR MANAGEMENT

    function addValidator(
        address _validator
    ) external onlyOwner {

        require(
            _validator != address(0),
            "Invalid validator address"
        );

        require(
            !validators[_validator],
            "Validator already exists"
        );

        validators[_validator] = true;

        validatorCount++;

        emit ValidatorAdded(_validator);
    }

    function removeValidator(
        address _validator
    ) external onlyOwner {

        require(
            validators[_validator],
            "Validator does not exist"
        );

        validators[_validator] = false;

        validatorCount--;

        emit ValidatorRemoved(_validator);
    }

    // CASE MANAGEMENT

    function createVerificationCase(
        uint256 _caseId
    ) external onlyOwner {

        require(
            verificationCases[_caseId].createdAt == 0,
            "Case already exists"
        );

        verificationCases[_caseId] = VerificationCase({
            caseId: _caseId,
            verified: false,
            approvalCount: 0,
            createdAt: block.timestamp
        });

        emit CaseCreated(_caseId);
    }

    // VERIFICATION LOGIC

    function verifyCase(
        uint256 _caseId
    )
        external
        onlyValidator
        caseExists(_caseId)
    {

        VerificationCase storage verificationCase =
            verificationCases[_caseId];

        require(
            !verificationCase.verified,
            "Case already approved"
        );

        require(
            !hasVerified[_caseId][msg.sender],
            "Validator already approved this case"
        );

        hasVerified[_caseId][msg.sender] = true;

        verificationCase.approvalCount++;

        verificationHistory[_caseId].push(
            VerificationRecord({
                validator: msg.sender,
                timestamp: block.timestamp
            })
        );

        emit CaseVerified(
            _caseId,
            msg.sender
        );

        /*
         * Approval Threshold
         * ------------------------------------------------
         * MVP Rule:
         * Case becomes verified after 2 approvals.
         *
         * This can later become configurable.
         */

        if (verificationCase.approvalCount >= 2) {

            verificationCase.verified = true;

            emit CaseApproved(_caseId);
        }
    }

    // VIEW FUNCTIONS

    function isCaseVerified(
        uint256 _caseId
    )
        external
        view
        caseExists(_caseId)
        returns (bool)
    {
        return verificationCases[_caseId].verified;
    }

    function getApprovalCount(
        uint256 _caseId
    )
        external
        view
        caseExists(_caseId)
        returns (uint256)
    {
        return verificationCases[_caseId].approvalCount;
    }

    function getVerificationHistory(
        uint256 _caseId
    )
        external
        view
        caseExists(_caseId)
        returns (VerificationRecord[] memory)
    {
        return verificationHistory[_caseId];
    }
}

